import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { format } from "prettier";
import openapiTS, { astToString } from "openapi-typescript";
const contract = JSON.parse(
  execFileSync("../backend/.venv/bin/python", ["scripts/export_openapi.py"], {
    encoding: "utf8",
  }),
);
const output = await format(
  "// Generated by pnpm generate:api. Do not edit.\n" +
    astToString(await openapiTS(contract)),
  { parser: "typescript" },
);
const path = "src/api/schema.d.ts";
if (process.argv.includes("--check")) {
  if (readFileSync(path, "utf8") !== output)
    throw new Error("OpenAPI types are stale: run pnpm generate:api");
} else writeFileSync(path, output);
